<script>
// Build bar chart dynamically
const companies = [
  { rank: 1, name: 'NVIDIA', ticker: 'NVDA', cap: 4.820, country: 'US' },
  { rank: 2, name: 'Alphabet', ticker: 'GOOG', cap: 4.025, country: 'US' },
  { rank: 3, name: 'Apple', ticker: 'AAPL', cap: 3.871, country: 'US' },
  { rank: 4, name: 'Microsoft', ticker: 'MSFT', cap: 3.123, country: 'US' },
  { rank: 5, name: 'Amazon', ticker: 'AMZN', cap: 2.685, country: 'US' },
  { rank: 6, name: 'Broadcom', ticker: 'AVGO', cap: 1.889, country: 'US' },
  { rank: 7, name: 'TSMC', ticker: 'TSM', cap: 1.884, country: 'TW' },
  { rank: 8, name: 'Saudi Aramco', ticker: '2222', cap: 1.774, country: 'SA' },
  { rank: 9, name: 'Meta', ticker: 'META', cap: 1.712, country: 'US' },
  { rank: 10, name: 'Tesla', ticker: 'TSLA', cap: 1.459, country: 'US' },
  { rank: 11, name: 'Berkshire H.', ticker: 'BRK', cap: 1.024, country: 'US' },
];

const maxCap = 4.820;
const barColors = [
  '#76b900', // NVIDIA green
  '#4285f4', // Google blue
  '#a2aaad', // Apple silver
  '#00a4ef', // Microsoft blue
  '#ff9900', // Amazon orange
  '#cc092f', // Broadcom red
  '#006eb8', // TSMC blue
  '#007a3d', // Aramco green
  '#0668E1', // Meta blue
  '#cc0000', // Tesla red
  '#6f42c1', // Berkshire purple
];

const barChart = document.getElementById('barChart');

companies.forEach((c, i) => {
  const pct = (c.cap / maxCap) * 100;
  const row = document.createElement('div');
  row.className = 'bar-row';

  // Insert top-5 divider
  if (i === 5) {
    const divider = document.createElement('hr');
    divider.className = 'top5-divider';
    barChart.appendChild(divider);
  }

  row.innerHTML = `
    <span class="bar-rank">${c.rank}</span>
    <span class="bar-company">${c.name}</span>
